types.schema_json:
{
  "name": "AccountingMethod",
  "package": "accounting_method",
  "description": "AccountingMethod identifies which RPC an event relates to.",
  "fields": []
}

{
  "name": "ProjectConfig",
  "package": "project_config",
  "description": "Stub — will be replaced by GenerateProjectConfig.",
  "fields": []
}

{
  "name": "Services",
  "package": "services_config",
  "fields": [
    {
      "name": "kmaker_config",
      "type": "message",
      "message": {
        "name": "Config",
        "package": "kmaker",
        "description": "Config is rendered by operator and mounted into kmaker at startup.",
        "fields": [
          {
            "name": "cluster_name",
            "type": "string",
            "description": "cluster_name is the logical Schematic cluster this kmaker signs for.",
            "required": true,
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "listener",
            "type": "message",
            "description": "listener is the gRPC bind address for kmaker.",
            "required": true,
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ],
            "message": {
              "name": "Host",
              "package": "host",
              "description": "Host identifies a network endpoint by hostname/IP and port.\n The host field accepts either an FQDN or an IP address (v4/v6).",
              "fields": [
                {
                  "name": "host",
                  "type": "string",
                  "description": "Hostname or IP address (e.g. \"api.example.com\" or \"10.0.0.1\").",
                  "required": true,
                  "constraints": [
                    "must be a valid hostname or IP address",
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_host",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "port",
                  "type": "int32",
                  "description": "Port number (1-65535).",
                  "constraints": [
                    "must be a valid network port (1-65535)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_net_port",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "protocol",
                  "type": "enum",
                  "description": "Transport protocol. Default TCP (zero value).",
                  "enum_values": [
                    {
                      "name": "TCP",
                      "number": 0
                    },
                    {
                      "name": "UDP",
                      "number": 1
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "logger",
            "type": "message",
            "description": "logger configures kmaker process logging.",
            "message": {
              "name": "LoggerConfig",
              "package": "logger",
              "description": "LoggerConfig represents the configuration for a logger instance.\n It controls the output format, verbosity level, and formatting options.\n\n Example usage:\n   - Development mode with console output and pretty printing for local debugging\n   - Production mode with JSON output and no pretty printing for log aggregation",
              "fields": [
                {
                  "name": "name",
                  "type": "string",
                  "description": "Name is the logger name/component identifier",
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "format",
                  "type": "enum",
                  "description": "Format determines the output format for log messages (JSON or console)\n Default: FORMAT_JSON in production, FORMAT_CONSOLE in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "FORMAT_JSON",
                      "number": 1,
                      "description": "FORMAT_JSON outputs logs as JSON objects, ideal for structured logging and log aggregation systems"
                    },
                    {
                      "name": "FORMAT_CONSOLE",
                      "number": 2,
                      "description": "FORMAT_CONSOLE outputs logs in a human-readable console format, ideal for development and debugging"
                    }
                  ]
                },
                {
                  "name": "level",
                  "type": "enum",
                  "description": "Level sets the minimum severity level for log messages to be output\n Messages below this level will be filtered out\n Default: LEVEL_INFO in production, LEVEL_DEBUG in development",
                  "constraint_infos": [
                    {
                      "rule": "assert_enum_defined",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ],
                  "enum_values": [
                    {
                      "name": "LEVEL_TRACE",
                      "number": 1,
                      "description": "LEVEL_TRACE is the most verbose log level, used for detailed debugging information"
                    },
                    {
                      "name": "LEVEL_DEBUG",
                      "number": 2,
                      "description": "LEVEL_DEBUG is used for debugging information, less verbose than trace"
                    },
                    {
                      "name": "LEVEL_INFO",
                      "number": 3,
                      "description": "LEVEL_INFO is used for informational messages about normal operations"
                    },
                    {
                      "name": "LEVEL_WARN",
                      "number": 4,
                      "description": "LEVEL_WARN is used for warning messages about potentially problematic situations"
                    },
                    {
                      "name": "LEVEL_ERROR",
                      "number": 5,
                      "description": "LEVEL_ERROR is used for error messages about failures and problems"
                    }
                  ]
                },
                {
                  "name": "development",
                  "type": "bool",
                  "description": "Development enables development mode which:\n   - Uses console format by default\n   - Enables stack traces for warnings and errors\n   - Uses more human-readable timestamps\n Default: false (production mode)"
                },
                {
                  "name": "pretty_print",
                  "type": "bool",
                  "description": "PrettyPrint enables pretty-printed output for JSON format\n This makes JSON logs more readable but increases output size\n Should be disabled in production for performance\n Default: false"
                },
                {
                  "name": "output_paths",
                  "type": "string",
                  "description": "OutputPaths is a list of file paths or URLs to write logs to\n Use \"stdout\" or \"stderr\" for console output\n Example: [\"stdout\", \"/var/log/app.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "error_output_paths",
                  "type": "string",
                  "description": "ErrorOutputPaths is a list of file paths or URLs to write error logs to\n Use \"stderr\" for console error output\n Example: [\"stderr\", \"/var/log/app-errors.log\"]",
                  "repeated": true,
                  "constraints": [
                    "must be a valid file path (type: PATH_ANY)",
                    "maximum size: 8 elements",
                    "maximum element size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_file_path",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "PATH_ANY",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_element_size",
                      "target": "element",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "disable_caller",
                  "type": "bool",
                  "description": "DisableCaller disables automatic inclusion of caller information (file:line) in log entries\n Default: false (caller information is included)"
                },
                {
                  "name": "disable_stacktrace",
                  "type": "bool",
                  "description": "DisableStacktrace disables automatic stacktraces for error-level and above log entries\n Default: false (stacktraces are included for errors)"
                },
                {
                  "name": "initial_fields",
                  "type": "map",
                  "description": "InitialFields is a map of fields to include in every log entry\n Useful for adding context like service name, version, environment, etc.\n Example: {\"service\": \"api\", \"version\": \"1.0.0\", \"environment\": \"production\"}",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 32 entries",
                    "maximum key size: 32768 bytes (default)",
                    "maximum value size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32,
                      "unit": "entries",
                      "source": "annotation"
                    },
                    {
                      "rule": "default_max_key_size",
                      "target": "key",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    },
                    {
                      "rule": "default_max_value_size",
                      "target": "value",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ],
                  "map_key_type": "string",
                  "map_value_type": "string"
                }
              ]
            }
          },
          {
            "name": "cluster_ca",
            "type": "message",
            "description": "cluster_ca holds trust anchors that kernel nodes should trust.",
            "repeated": true,
            "constraints": [
              "maximum size: 16 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 16,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "X509Cert",
              "package": "x509",
              "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the certificate",
                  "constraints": [
                    "maximum size: 256 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM certificate block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "signing_ca",
            "type": "message",
            "description": "signing_ca is the cluster signing CA used to issue kernel certificates.\n The private key is present in the mounted kmaker config and must be backed\n by a Kubernetes Secret owned by operator.",
            "required": true,
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ],
            "message": {
              "name": "X509CertChain",
              "package": "x509",
              "description": "X509CertChain contains a certificate chain and optional private key.\n chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.\n When key is present, the chain is a full credential suitable for TLS.",
              "fields": [
                {
                  "name": "chain",
                  "type": "message (recursive reference: x509.X509Cert)",
                  "description": "chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.",
                  "repeated": true,
                  "constraints": [
                    "maximum size: 8 elements",
                    "minimum size: 1"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8,
                      "unit": "elements",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_min_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1,
                      "unit": "elements",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "key",
                  "type": "message",
                  "description": "optional private key for the leaf cert; present when chain is a full credential.",
                  "message": {
                    "name": "Key",
                    "package": "key",
                    "description": "Key represents a private cryptographic key (alias for ProtoKey).",
                    "fields": [
                      {
                        "name": "id",
                        "type": "string",
                        "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                        "required": true,
                        "constraints": [
                          "maximum size: 256 bytes",
                          "minimum size: 1"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 256,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_min_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1,
                            "unit": "bytes",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "base64",
                        "type": "string",
                        "description": "Base64 contains the base64url-encoded PEM private key block",
                        "required": true,
                        "constraints": [
                          "must be base64 encoded",
                          "encoding type: ENC_TYPE_KEY_PRIVATE_ANY",
                          "maximum size: 16384 bytes"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_max_size",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 16384,
                            "unit": "bytes",
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_base64",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_enc_type",
                            "target": "field",
                            "value_kind": "enum",
                            "enum_value": "ENC_TYPE_KEY_PRIVATE_ANY",
                            "source": "annotation"
                          }
                        ]
                      },
                      {
                        "name": "created",
                        "type": "int64",
                        "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                        "required": true,
                        "constraints": [
                          "must be \u003e= 1735689600",
                          "must be \u003c= 8045740800"
                        ],
                        "constraint_infos": [
                          {
                            "rule": "assert_required",
                            "target": "field",
                            "value_kind": "bool",
                            "bool_value": true,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_ge",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 1735689600,
                            "source": "annotation"
                          },
                          {
                            "rule": "assert_le",
                            "target": "field",
                            "value_kind": "int",
                            "int_value": 8045740800,
                            "source": "annotation"
                          }
                        ]
                      }
                    ]
                  }
                },
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is an optional stable key for chain collections.",
                  "constraints": [
                    "maximum size: 256 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "spiffe_prefix",
            "type": "string",
            "description": "spiffe_prefix is the SPIFFE trust domain for kernel SPIFFE URI SANs: the\n URI authority, so it must not contain '/'. Certificates minted here\n receive spiffe://\u003cspiffe_prefix\u003e/kernel. Operator supplies this from\n operator.Config.spiffe_prefix.",
            "default": "local.dev",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "token_audience",
            "type": "string",
            "description": "token_audience is the required Kubernetes TokenReview audience.",
            "default": "kmaker",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "kernel_service_accounts",
            "type": "message",
            "description": "kernel_service_accounts are Kubernetes service accounts allowed to request\n kernel certificates. Empty means namespace=schematic, name=kernel.",
            "repeated": true,
            "constraints": [
              "maximum size: 32 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "KernelServiceAccount",
              "package": "kmaker",
              "fields": [
                {
                  "name": "namespace",
                  "type": "string",
                  "required": true,
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "name",
                  "type": "string",
                  "required": true,
                  "constraints": [
                    "maximum size: 128 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 128,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "trace_id",
                  "type": "string",
                  "constraints": [
                    "maximum size: 32768 bytes (default)"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "default_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 32768,
                      "defaulted": true,
                      "unit": "bytes",
                      "source": "default_bound"
                    }
                  ]
                },
                {
                  "name": "noop",
                  "type": "bool"
                }
              ]
            }
          },
          {
            "name": "kernel_cert_lifetime_seconds",
            "type": "int64",
            "description": "kernel_cert_lifetime_seconds caps issued kernel certificate lifetimes.",
            "default": 86400,
            "constraints": [
              "duration constraint: DURATION_TYPE_POSITIVE"
            ],
            "constraint_infos": [
              {
                "rule": "assert_duration",
                "target": "field",
                "value_kind": "enum",
                "enum_value": "DURATION_TYPE_POSITIVE",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "tls",
            "type": "message (recursive reference: x509.X509CertChain)",
            "description": "tls is the optional serving certificate for kmaker's own gRPC listener.\n When unset, kmaker starts without transport TLS for local/dev only."
          },
          {
            "name": "health_probe_port",
            "type": "int32",
            "description": "health_probe_port is the plaintext gRPC port for k8s health probes.\n Kmaker's hand-written bootstrap bypasses the generated ServiceManager,\n so this field must be on Kmaker.Config (not only on Grpcconfig.Config).\n Default matches the platform-wide health probe port.",
            "default": 8444
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    }
  ]
}

fields.description:
InitialFields is a map of fields to include in every log entry
 Useful for adding context like service name, version, environment, etc.
 Example: {"service": "api", "version": "1.0.0", "environment": "production"}

types.schema_json:
{
  "name": "TenantConfig",
  "package": "tenant_config",
  "description": "Stub — will be replaced by GenerateTenantConfig.",
  "fields": []
}

{
  "name": "Config",
  "package": "kmaker",
  "description": "Config is rendered by operator and mounted into kmaker at startup.",
  "fields": [
    {
      "name": "cluster_name",
      "type": "string",
