          {
            "name": "disable_stacktrace",
            "type": "bool",
            "description": "DisableStacktrace disables automatic stacktraces for error-level and above log entries\n Default: false (stacktraces are included for errors)"
          },
          {
            "name": "initial_fields",
            "type": "map",
            "description": "InitialFields is a map of fields to include in every log entry\n Useful for adding context like service name, version, environment, etc.\n Example: {\"service\": \"api\", \"version\": \"1.0.0\", \"environment\": \"production\"}",
            "repeated": true,
            "constraints": [
              "maximum size: 32 entries",
              "maximum key size: 32768 bytes (default)",
              "maximum value size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32,
                "unit": "entries",
                "source": "annotation"
              },
              {
                "rule": "default_max_key_size",
                "target": "key",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              },
              {
                "rule": "default_max_value_size",
                "target": "value",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ],
            "map_key_type": "string",
            "map_value_type": "string"
          }
        ]
      }
    },
    {
      "name": "cluster_ca",
      "type": "message",
      "description": "cluster_ca holds trust anchors that kernel nodes should trust.",
      "repeated": true,
      "constraints": [
        "maximum size: 16 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 16,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "X509Cert",
        "package": "x509",
        "description": "ProtoCert represents an X.509 certificate.\n The certificate is stored as a base64-encoded PEM block.\n Use NewProtoCert() in Go with DER-encoded certificate bytes to create.",
        "fields": [
          {
            "name": "id",
            "type": "string",
            "description": "Id is a unique identifier for the certificate",
            "constraints": [
              "maximum size: 256 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 256,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "base64",
            "type": "string",
            "description": "Base64 contains the base64url-encoded PEM certificate block",
            "required": true,
            "constraints": [
              "must be base64 encoded",
              "maximum size: 16384 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 16384,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
          }
        ]
      }
    },
    {
      "name": "signing_ca",
      "type": "message",
      "description": "signing_ca is the cluster signing CA used to issue kernel certificates.\n The private key is present in the mounted kmaker config and must be backed\n by a Kubernetes Secret owned by operator.",
      "required": true,
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ],
      "message": {
        "name": "X509CertChain",
        "package": "x509",
        "description": "X509CertChain contains a certificate chain and optional private key.\n chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.\n When key is present, the chain is a full credential suitable for TLS.",
        "fields": [
          {
            "name": "chain",
            "type": "message (recursive reference: x509.X509Cert)",
            "description": "chain[0] is the leaf (end-entity) cert, followed by intermediates, ordered toward root.",
            "repeated": true,
            "constraints": [
              "maximum size: 8 elements",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 8,
                "unit": "elements",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "elements",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "key",
            "type": "message",
            "description": "optional private key for the leaf cert; present when chain is a full credential.",
            "message": {
              "name": "Key",
              "package": "key",
              "description": "Key represents a private cryptographic key (alias for ProtoKey).",
              "fields": [
                {
                  "name": "id",
                  "type": "string",
                  "description": "Id is a unique identifier for the key (corresponds to kid in JWK)",
                  "required": true,
                  "constraints": [
                    "maximum size: 256 bytes",
                    "minimum size: 1"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 256,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_min_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "base64",
                  "type": "string",
                  "description": "Base64 contains the base64url-encoded PEM private key block",
                  "required": true,
                  "constraints": [
                    "must be base64 encoded",
                    "encoding type: ENC_TYPE_KEY_PRIVATE_ANY",
                    "maximum size: 16384 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 16384,
                      "unit": "bytes",
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_base64",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_enc_type",
                      "target": "field",
                      "value_kind": "enum",
                      "enum_value": "ENC_TYPE_KEY_PRIVATE_ANY",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "created",
                  "type": "int64",
                  "description": "Created is the Unix epoch timestamp (seconds) when the key was created\n Valid range: 1735689600 (2025-01-01) to 8045740800 (2225-01-01)",
                  "required": true,
                  "constraints": [
                    "must be \u003e= 1735689600",
                    "must be \u003c= 8045740800"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 1735689600,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 8045740800,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "id",
            "type": "string",
