      "constraint_infos": [
        {
          "rule": "default_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32768,
          "defaulted": true,
          "unit": "bytes",
          "source": "default_bound"
        }
      ]
    },
    {
      "name": "kernel_service_accounts",
      "type": "message",
      "description": "kernel_service_accounts are Kubernetes service accounts allowed to request\n kernel certificates. Empty means namespace=schematic, name=kernel.",
      "repeated": true,
      "constraints": [
        "maximum size: 32 elements"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 32,
          "unit": "elements",
          "source": "annotation"
        }
      ],
      "message": {
        "name": "KernelServiceAccount",
        "package": "kmaker",
        "fields": [
          {
            "name": "namespace",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "name",
            "type": "string",
            "required": true,
            "constraints": [
              "maximum size: 128 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 128,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "trace_id",
            "type": "string",
            "constraints": [
              "maximum size: 32768 bytes (default)"
            ],
            "constraint_infos": [
              {
                "rule": "default_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 32768,
                "defaulted": true,
                "unit": "bytes",
                "source": "default_bound"
              }
            ]
          },
          {
            "name": "noop",
            "type": "bool"
          }
        ]
      }
    },
    {
      "name": "kernel_cert_lifetime_seconds",
      "type": "int64",
      "description": "kernel_cert_lifetime_seconds caps issued kernel certificate lifetimes.",
      "default": 86400,
      "constraints": [
        "duration constraint: DURATION_TYPE_POSITIVE"
      ],
      "constraint_infos": [
        {
          "rule": "assert_duration",
          "target": "field",
          "value_kind": "enum",
          "enum_value": "DURATION_TYPE_POSITIVE",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "tls",
