{
  "name": "McpRequest",
  "package": "mcp",
  "description": "McpRequest carries one JSON-RPC frame from an MCP client to the service.",
  "fields": [
    {
      "name": "payload",
      "type": "string",
      "description": "payload is one complete JSON-RPC 2.0 message, serialized.\n\n Client frames are tool calls and protocol handshakes, both small; the\n bound is a ceiling on a malformed or hostile frame, not a working limit.",
      "required": true,
      "constraints": [
        "maximum size: 1048576 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1048576,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    }
  ]
}

{
  "name": "McpResponse",
  "package": "mcp",
  "description": "McpResponse carries one JSON-RPC frame from the service back to the client.",
  "fields": [
    {
      "name": "payload",
      "type": "string",
      "description": "payload is one complete JSON-RPC 2.0 message, serialized.\n\n A tool result holding a page of records is the large case, so this bound\n is well above the 32 KB default for an unannotated string. It sits under\n the 4 MiB gRPC message default so that a frame the service is willing to\n validate is also one an ordinary client will accept; a handler turns an\n over-size result into a JSON-RPC error on that request rather than failing\n the whole stream.",
      "required": true,
      "constraints": [
        "maximum size: 4000000 bytes"
      ],
      "constraint_infos": [
        {
          "rule": "assert_required",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        },
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 4000000,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    }
  ]
}

{
  "name": "OpaPolicy",
  "package": "opalib",
  "description": "OpaPolicy defines an OPA policy bundle for authorization evaluation.\n The bundle is a filesystem.Directory tree containing .rego policy files.",
  "fields": [
    {
      "name": "entry_point",
      "type": "string",
      "description": "entry_point specifies the main package/decision point for policy evaluation.",
      "constraints": [
        "maximum size: 256 bytes",
        "minimum size: 1"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 256,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_min_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 1,
          "unit": "bytes",
          "source": "annotation"
        }
      ]
    },
    {
      "name": "bundle",
      "type": "message",
      "description": "bundle is the directory tree containing .rego policy files.",
      "message": {
        "name": "Directory",
        "package": "filesystem",
        "description": "Directory represents a directory node in a filesystem tree.\n Directories are recursive — each may contain child directories and files.",
        "fields": [
          {
            "name": "name",
            "type": "string",
            "description": "name is the directory name (not a path)",
            "required": true,
            "constraints": [
              "maximum size: 255 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 255,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "permission",
            "type": "message",
            "description": "permission is the Unix-style permission for this directory",
            "message": {
              "name": "Permission",
              "package": "filesystem",
              "description": "Permission represents Unix-style file permissions (e.g., 755).\n Each field is a 3-bit mask: read (4) + write (2) + execute (1).",
              "fields": [
                {
                  "name": "owner",
                  "type": "uint32",
                  "description": "owner permission bits (0-7)",
                  "constraints": [
                    "must be \u003e= 0",
                    "must be \u003c= 7"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 0,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 7,
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "group",
                  "type": "uint32",
                  "description": "group permission bits (0-7)",
                  "constraints": [
                    "must be \u003e= 0",
                    "must be \u003c= 7"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 0,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 7,
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "other",
                  "type": "uint32",
                  "description": "other permission bits (0-7)",
                  "constraints": [
                    "must be \u003e= 0",
                    "must be \u003c= 7"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_ge",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 0,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_le",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 7,
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          },
          {
            "name": "directories",
            "type": "message (recursive reference: filesystem.Directory)",
            "description": "directories holds zero or more child directories",
            "repeated": true,
            "constraints": [
              "maximum size: 10000 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 10000,
                "unit": "elements",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "files",
            "type": "message",
            "description": "files holds zero or more files in this directory",
            "repeated": true,
            "constraints": [
              "maximum size: 10000 elements"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 10000,
                "unit": "elements",
                "source": "annotation"
              }
            ],
            "message": {
              "name": "File",
              "package": "filesystem",
              "description": "File represents a single file with permissions and content.",
              "fields": [
                {
                  "name": "name",
                  "type": "string",
                  "description": "name is the file name (not a path)",
                  "required": true,
                  "constraints": [
                    "maximum size: 255 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_required",
                      "target": "field",
                      "value_kind": "bool",
                      "bool_value": true,
                      "source": "annotation"
                    },
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 255,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                },
                {
                  "name": "permission",
                  "type": "message (recursive reference: filesystem.Permission)",
                  "description": "permission is the Unix-style permission for this file"
                },
                {
                  "name": "content",
                  "type": "bytes",
                  "description": "content is the raw file content (max 10 MB)",
                  "constraints": [
                    "maximum size: 10485760 bytes"
                  ],
                  "constraint_infos": [
                    {
                      "rule": "assert_max_size",
                      "target": "field",
                      "value_kind": "int",
                      "int_value": 10485760,
                      "unit": "bytes",
                      "source": "annotation"
                    }
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    {
      "name": "created",
      "type": "int64",
      "description": "created is the Unix epoch timestamp (seconds) when the policy was created.",
      "constraints": [
        "must be \u003e= 1735689600",
        "must be \u003c= 8045740800"
      ],
      "constraint_infos": [
        {
          "rule": "assert_ge",
          "target": "field",
          "value_kind": "int",
          "int_value": 1735689600,
          "source": "annotation"
        },
        {
          "rule": "assert_le",
          "target": "field",
          "value_kind": "int",
          "int_value": 8045740800,
          "source": "annotation"
        }
      ]
    },
    {
      "name": "version",
      "type": "string",
      "description": "version is an optional version string for this policy (e.g., \"1.0.0\").",
      "constraints": [
        "maximum size: 64 bytes",
        "must be a valid semantic version"
      ],
      "constraint_infos": [
        {
          "rule": "assert_max_size",
          "target": "field",
          "value_kind": "int",
          "int_value": 64,
          "unit": "bytes",
          "source": "annotation"
        },
        {
          "rule": "assert_semver",
          "target": "field",
          "value_kind": "bool",
          "bool_value": true,
          "source": "annotation"
        }
      ]
    }
  ]
}

