    {
      "name": "value",
      "type": "message",
      "message": {
        "name": "Jwk",
        "package": "jwk",
        "description": "Jwk represents a JSON Web Key as defined in RFC 7517.\n It contains the public key parameters for RSA (e, n), EC (crv, x, y), or OKP (crv, x) keys.\n JWK is used for key distribution and verification in JSON-based protocols like JWT.",
        "fields": [
          {
            "name": "kty",
            "type": "enum",
            "description": "Kty is the key type parameter (RSA, EC, or OKP)",
            "enum_values": [
              {
                "name": "KEY_TYPE_RSA",
                "number": 1,
                "description": "KeyTypeRsa represents an RSA key type"
              },
              {
                "name": "KEY_TYPE_EC",
                "number": 2,
                "description": "KeyTypeEc represents an Elliptic Curve key type"
              },
              {
                "name": "KEY_TYPE_OKP",
                "number": 3,
                "description": "KeyTypeOkp represents an Octet Key Pair (EdDSA) key type"
              }
            ]
          },
          {
            "name": "alg",
            "type": "string",
            "description": "Alg is the algorithm intended for use with the key (e.g., \"RS384\", \"ES256\", \"EdDSA\")",
            "required": true,
            "constraints": [
              "maximum size: 64 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "kid",
            "type": "string",
            "description": "Kid is the key ID used to match keys with signatures",
            "required": true,
            "constraints": [
              "maximum size: 512 bytes",
              "minimum size: 1"
            ],
            "constraint_infos": [
              {
                "rule": "assert_required",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              },
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 512,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_min_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 1,
                "unit": "bytes",
                "source": "annotation"
              }
            ]
          },
          {
            "name": "use",
            "type": "enum",
            "description": "Use indicates the intended use of the key (sig for signatures, enc for encryption)",
            "enum_values": [
              {
                "name": "JWK_USE_TYPE_SIG",
                "number": 1,
                "description": "JwkUseTypeSig indicates the key is used for digital signatures"
              },
              {
                "name": "JWK_USE_TYPE_ENC",
                "number": 2,
                "description": "JwkUseTypeEnc indicates the key is used for encryption"
              }
            ]
          },
          {
            "name": "e",
            "type": "string",
            "description": "E is the RSA public exponent (base64url encoded without padding)",
            "constraints": [
              "must be base64 encoded",
              "maximum size: 64 bytes"
            ],
            "constraint_infos": [
              {
                "rule": "assert_max_size",
                "target": "field",
                "value_kind": "int",
                "int_value": 64,
                "unit": "bytes",
                "source": "annotation"
              },
              {
                "rule": "assert_base64",
                "target": "field",
                "value_kind": "bool",
                "bool_value": true,
                "source": "annotation"
              }
            ]
